def available_budget(limit, spent=0, reserved=0):
    """Return the nonnegative budget remaining after spending and reservations."""
    if min(limit, spent, reserved) < 0:
        raise ValueError("limit, spent, and reserved must be nonnegative")
    return max(limit - spent - reserved, 0)

